 LR:{countryCode:"LR",countryName:"Liberia",currency:"LRD",status:"review_required",authority:"Liberia Revenue Authority (LRA)",rulesVersion:"Liberia Revenue Code amended 2020 — LRA notices 2026",rulesEffectiveFrom:"",calculationModules:[],taxFacts:[{taxType:"OTHER",label:"Goods and Services Tax — taux selon secteur",value:"7 % à 15 % ; services visés : 13 % ; télécommunications : 15 %",detail:"La LRA présente une GST sectorielle de 7 % à 15 % pour les restaurants, hôtels, location de véhicules, télécommunications et fabricants. Un avis du 7 avril 2026 annonce 13 % pour certains services et maintient 15 % pour les télécommunications ; ces catégories ne constituent pas un taux général uniforme.",legalReference:"LRA — Business Tax Kinds ; LRA notice, 7 April 2026",sourceUrl:"https://www.lra.gov.lr/domestic-tax-profile/businesstaxkinds/"},{taxType:"IS",label:"Business / Corporate Income Tax — activité générale",value:"25 %",detail:"Le document de stratégie de mobilisation des ressources 2025–2029 indique 25 % pour les entreprises générales, avec régimes distincts pour petites entreprises et secteurs spécifiques. Pas de calculateur activé.",legalReference:"Liberia Domestic Resource Mobilization Strategy 2025–2029, Annex 5",sourceUrl:"https://revenue.lra.gov.lr/wp-content/uploads/2025/09/Liberia-DRM-Strategy-2025-2029.pdf"}],taxScales:[],legalSources:[{label:"LRA — Business Tax Kinds",url:"https://www.lra.gov.lr/domestic-tax-profile/businesstaxkinds/"},{label:"LRA — GST rate adjustment, 7 April 2026",url:"https://www.lra.gov.lr/important-revenue-noticeadjustment-to-goods-and-services-tax-gst-rates/"},{label:"LRA — Liberia Revenue Code and amendments",url:"https://revenue.lra.gov.lr/laws-issuances/"},{label:"Liberia Domestic Resource Mobilization Strategy 2025–2029",url:"https://revenue.lra.gov.lr/wp-content/uploads/2025/09/Liberia-DRM-Strategy-2025-2029.pdf"}],rules:[]},
 MR:{countryCode:"MR",countryName:"Mauritanie",currency:"MRU",status:"research_required",authority:"Direction générale des Impôts (DGI)",rulesVersion:"CGI 2019 — amendements LF 2026 à consolider",rulesEffectiveFrom:"",calculationModules:[],taxFacts:[{taxType:"OTHER",label:"État documentaire",value:"CGI 2019 et loi de finances 2026 disponibles",detail:"La DGI publie le CGI et les lois de finances dans sa rubrique de documentation. Les dispositions modifiées par la LF 2026 doivent être rapprochées du texte consolidé avant toute activation de taux ou de calculateur.",legalReference:"Loi n° 2019-018 du 29 avril 2019 ; Loi de finances 2026",sourceUrl:"https://impots.gov.mr/DGI/"}],taxScales:[],legalSources:[{label:"DGI Mauritanie — textes fiscaux codifiés et lois de finances",url:"https://impots.gov.mr/DGI/"},{label:"Loi de finances 2026 — Ministère des Finances",url:"https://www.finances.gov.mr/sites/default/files/2026-01/Loi%20de%20Finances%20pour%20l%E2%80%99ann%C3%A9e%202026.pdf"}],rules:[]},
 NE:{countryCode:"NE",countryName:"Niger",currency:"XOF",status:"research_required",authority:"Direction générale des Impôts (DGI)",rulesVersion:"CGI 2025 — mise à jour LF 2025 ; LF 2026 à contrôler",rulesEffectiveFrom:"",calculationModules:[],taxFacts:[{taxType:"VAT",label:"TVA — taux normal",value:"19 %",detail:"Taux normal prévu par l’article 226 du CGI 2025. Des taux réduits de 10 % et 5 % s’appliquent à des catégories précisément énumérées ; ils ne sont pas activés dans le moteur.",legalReference:"CGI 2025, art. 226",sourceUrl:"https://www.impots.gouv.ne/media/telech/LIVRE%201%20ET%202%20ENTIER%20CGI%202025.pdf"},{taxType:"IS",label:"Impôt sur les bénéfices",value:"30 %",detail:"Taux du bénéfice net imposable selon l’article 27 ; l’impôt minimum forfaitaire varie selon l’activité et ne peut être réduit à un taux unique.",legalReference:"CGI 2025, art. 27 et 37",sourceUrl:"https://www.impots.gouv.ne/media/telech/LIVRE%201%20ET%202%20ENTIER%20CGI%202025.pdf"},{taxType:"OTHER",label:"Impôt minimum forfaitaire",value:"0,75 % à 15 % selon activité et assiette",detail:"Taux de 0,75 % pour les entreprises industrielles, 2,50 % pour les autres activités, 5 % ou 15 % pour certaines activités taxées sur marge brute.",legalReference:"CGI 2025, art. 37",sourceUrl:"https://www.impots.gouv.ne/media/telech/LIVRE%201%20ET%202%20ENTIER%20CGI%202025.pdf"}],taxScales:[],legalSources:[{label:"DGI Niger — Code général des impôts 2025",url:"https://www.impots.gouv.ne/media/telech/LIVRE%201%20ET%202%20ENTIER%20CGI%202025.pdf"},{label:"Ministère de l’Économie et des Finances — Niger",url:"https://www.finances.gouv.ne/"}],rules:[]},
